from typing import List

def wrap(text: str, cols: int) -> List[str]:
    lines = []
    while len(text) > cols:
        end = text.rfind(' ', 0, cols + 1)
        if end == -1:
            end = cols
        line, text = text[:end], text[end:]
        lines.append(line)

    return lines

if __name__ == "__main__":
    print(wrap("This is an example text to be wrapped", 20))
    # Output:
    # ['This is an', 'example text', 'to be wrapped']
